	@Test
	void mixedScopesPreserveDuplicatesAndLocalAssignments() {
		useDefaultStrategy();
		var mixed = new QueryRoot(new Union(new DownstreamPattern(), pattern()));
		var scoped = new QueryRoot(new Union(new DownstreamPattern(), new Extension(new SingletonSet(),
				new ExtensionElem(new ValueConstant(VF.createIRI("urn:local")), "s"),
				new ExtensionElem(Var.of("s"), "used"))));
		try (SailConnection connection = repository.getSail().getConnection()) {
			var matching = QueryResults.asList(connection.evaluate(mixed, null, parameter("s", SUBJECT), true));
			assertThat(matching).hasSize(2).allSatisfy(row -> {
				assertThat(row.getBindingNames()).containsExactlyInAnyOrder("s", "o");
				assertThat(row.getValue("s")).isEqualTo(SUBJECT);
				assertThat(row.getValue("o")).isEqualTo(VF.createLiteral("o"));
			});
			assertThat(QueryResults.asList(connection.evaluate(mixed, null,
					parameter("s", VF.createIRI("urn:absent")), true))).isEmpty();
			var rows = QueryResults.asList(connection.evaluate(scoped, null, parameter("s", SUBJECT), true));
			assertThat(rows).extracting(row -> row.getValue("s"))
					.containsExactlyInAnyOrder(SUBJECT,
							VF.createIRI("urn:local"));
			assertThat(rows).filteredOn(row -> row.hasBinding("used"))
					.singleElement()
					.satisfies(row -> assertThat(row.getValue("used")).isEqualTo(VF.createIRI("urn:local")));
		}
	}

