	@Test
	void legacyStrategyAndPipelineSeeOriginalInputAndStageOrder() {
		BindingSet parameters = parameter("hidden", SUBJECT);
		BindingSet selectedEmpty = new EmptyBindingSet();
		List<String> stages = new ArrayList<>();
		QueryOptimizer replace = (expr, data, input) -> {
			stages.add("replace");
			assertThat(input).isSameAs(parameters);
			var extension = (Extension) ((QueryRoot) expr).getArg();
			extension.setArg(new Extension(new SingletonSet(),
					new ExtensionElem(new ValueConstant(input.getValue("hidden")), "parameter")));
		};
		QueryOptimizer observe = (expr, data, input) -> {
			stages.add("observe");
			assertThat(input).isSameAs(selectedEmpty);
		};
		((MemoryStore) repository.getSail()).setEvaluationStrategyFactory(new DefaultEvaluationStrategyFactory() {
			@Override
			public EvaluationStrategy createEvaluationStrategy(Dataset dataset, TripleSource source,
					EvaluationStatistics statistics) {
				var strategy = new DefaultEvaluationStrategy(source, dataset, getFederatedServiceResolver(), 0,
						statistics) {
					@Override
					public TupleExpr optimize(TupleExpr expression, EvaluationStatistics stats, BindingSet input) {
						stages.add("optimize");
						assertThat(input).isSameAs(parameters);
						var envelope = (OpaqueEnvelope) ((QueryRoot) expression).getArg();
						envelope.replaceWith(envelope.getArg());
						return super.optimize(expression, stats, input);
					}

					@Override
					public QueryEvaluationStep precompile(TupleExpr expression) {
						stages.add("compile");
						QueryEvaluationStep step = super.precompile(expression);
						return input -> {
							stages.add("evaluate");
							assertThat(input).isSameAs(EmptyBindingSet.getInstance());
							return step.evaluate(input);
						};
					}

					@Override
					public QueryValueEvaluationStep precompile(ValueExpr expression, QueryEvaluationContext context) {
						if (expression instanceof HiddenRead) {
							return input -> input.hasBinding("hidden") ? input.getValue("hidden")
									: VF.createLiteral("unbound");
						}
						return super.precompile(expression, context);
					}
				};
				strategy.setOptimizerPipeline(new QueryOptimizerPipeline() {
					@Override
					public Iterable<QueryOptimizer> getOptimizers() {
						return List.of(replace, observe);
					}

					@Override
					public BindingSet getOptimizerInputBindings(QueryOptimizer optimizer, BindingSet input) {
						assertThat(input).isSameAs(parameters);
						stages.add("select");
						return optimizer == observe ? selectedEmpty : input;
					}
				});
				return strategy;
			}
		});
		var expression = new QueryRoot(new OpaqueEnvelope(
				new Extension(new SingletonSet(), new ExtensionElem(new HiddenRead(), "seen"))));
		try (SailConnection connection = repository.getSail().getConnection()) {
			var rows = QueryResults.asList(connection.evaluate(expression, null, parameters, true));
			assertThat(rows).singleElement().satisfies(row -> {
				assertThat(row.getBindingNames()).containsExactlyInAnyOrder("seen", "parameter");
				assertThat(row.getValue("parameter")).isEqualTo(SUBJECT);
				assertThat(row.getValue("seen")).isEqualTo(VF.createLiteral("unbound"));
			});
		}
		assertThat(stages).containsExactly("optimize", "select", "replace", "select", "observe", "compile", "evaluate");
		assertThat(expression.getArg()).isInstanceOf(OpaqueEnvelope.class);
	}

